   307	function replaceMarkedTable(contents, startMarker, endMarker, table, label) {
   308		const starts = [
   309			...contents.matchAll(new RegExp(escapeRegExp(startMarker), "g")),
   310		];
   311		const ends = [...contents.matchAll(new RegExp(escapeRegExp(endMarker), "g"))];
   312		if (
   313			starts.length === 0 ||
   314			ends.length === 0 ||
   315			starts[0].index > ends[0].index
   316		)
   317			throw new Error(`${label} markers are missing or out of order`);
   318		if (starts.length !== 1 || ends.length !== 1)
   319			throw new Error(`${label} markers are duplicated`);
   320		const endOffset = ends[0].index + endMarker.length;
   321		return `${contents.slice(0, starts[0].index)}${table}${contents.slice(endOffset)}`;
   322	}
