118	export function createDiagnosticError(kind, schemaPath) {
119		const error = new Error("nightly diagnostic failure");
120		error.diagnosticKind = ERROR_CLASSES.includes(kind) ? kind : "unknown";
121		error.schemaPath = safeSchemaPath(schemaPath);
122		return error;
123	}
