125	export function normalizeError(error, suppliedSchemaPath) {
126		const explicitKind = safeRead(error, "diagnosticKind");
127		const name = safeRead(error, "name");
128		const code = safeRead(error, "code");
129		let errorClass = "unknown";
130	
131		if (ERROR_CLASSES.includes(explicitKind)) errorClass = explicitKind;
132		else if (safeRead(error, "isAxiosError") === true || name === "AxiosError") {
133			errorClass = "axios";
134		} else if (
135			typeof code === "number" ||
136			name === "McpError" ||
137			name === "JSONRPCError"
138		) {
139			errorClass = "mcp";
140		} else if (name === "AssertionError") errorClass = "assertion";
141		else if (typeof code === "string" && TRANSPORT_CODES.has(code)) {
142			errorClass = "transport";
143		}
