 30	
 31	function assertCondition(condition, schemaPath, kind = "schema") {
 32		if (!condition) throw createDiagnosticError(kind, schemaPath);
 33	}
 34	
 35	function readFirstText(result) {
 36		const first = result?.content?.[0];
 37		assertCondition(first, "$.content[0]");
 38		assertCondition(first.type === "text", "$.content[0].type");
 39		assertCondition(typeof first.text === "string", "$.content[0].text");
 40		return first.text;
 41	}
 42	
 43	function expectJsonContent(result) {
 44		const text = readFirstText(result).trim();
 45		assertCondition(
 46			text.startsWith("{") || text.startsWith("["),
 47			"$.content[0].text",
 48		);
 49		try {
 50			return JSON.parse(text);
 51		} catch {
 52			throw createDiagnosticError("schema", "$.content[0].text");
 53		}
 54	}
 55	
 56	function parseLauncherConfig() {
 57		assertCondition(process.env.HEVY_API_KEY, undefined, "assertion");
 58		const command = process.env.HEVY_MCP_COMMAND?.trim();
 59		assertCondition(command, undefined, "assertion");
 60		const argsJson = process.env.HEVY_MCP_ARGS_JSON;
 61		assertCondition(argsJson, undefined, "assertion");
 62		let args;
 63		try {
 64			args = JSON.parse(argsJson);
 65		} catch {
 66			throw createDiagnosticError("assertion");
 67		}
 68		assertCondition(
 69			Array.isArray(args) &&
 70				args.length > 0 &&
 71				args.every((arg) => typeof arg === "string"),
 72			undefined,
 73			"assertion",
 74		);
 75		return { command, args };
 76	}
