 78	async function readPackageVersion() {
 79		try {
 80			const packageJson = JSON.parse(await readFile("package.json", "utf8"));
 81			return packageJson.version;
 82		} catch {
 83			return null;
 84		}
 85	}
 86	
 87	async function callOrIgnoreEmpty(client, name, args) {
 88		const result = await client.callTool({ name, arguments: args });
 89		if (result.isError) throw createDiagnosticError("mcp");
 90		const text = readFirstText(result).trim();
 91		if (!text) return { empty: true };
 92		return { empty: false, parsed: expectJsonContent(result) };
 93	}
 94	
 95	async function finishDiagnostics(summary, diagnosticsPath) {
 96		finalizeDiagnostics(summary);
 97		console.log(renderSummaryLine(summary));
 98		try {
 99			await writeDiagnostics(diagnosticsPath, summary);
100		} catch (error) {
101			console.error(
102				`::error::[nightly] status=fail category=lifecycle name=artifact-write error=${normalizeError(error).errorClass}`,
103			);
104			process.exitCode = 1;
105		}
106		if (summary.totals.failed > 0) process.exitCode = 1;
107	}
