 36	function waitForMcpResponse(child, id, timeoutMs = 10_000) {
 37		return new Promise((resolve, reject) => {
 38			let buffer = "";
 39			const timer = setTimeout(() => {
 40				cleanup();
 41				reject(new Error(`Timed out waiting for MCP response ${id}`));
 42			}, timeoutMs);
 43			const cleanup = () => {
 44				clearTimeout(timer);
 45				child.stdout.removeListener("data", onData);
 46				child.removeListener("error", onError);
 47				child.removeListener("exit", onExit);
 48			};
 49			const onData = (chunk) => {
 50				buffer += chunk.toString();
 51				for (const line of buffer.split("\n").slice(0, -1)) {
 52					if (!line.trim()) continue;
 53					let message;
 54					try {
 55						message = JSON.parse(line);
 56					} catch {
 57						continue;
 58					}
 59					if (message?.id === id) {
 60						cleanup();
 61						resolve(message);
 62						return;
 63					}
 64				}
 65				buffer = buffer.includes("\n")
 66					? buffer.slice(buffer.lastIndexOf("\n") + 1)
 67					: buffer;
 68			};
 69			const onError = (error) => {
 70				cleanup();
 71				reject(error);
 72			};
 73			const onExit = (code, signal) => {
 74				cleanup();
 75				reject(
 76					new Error(`MCP process exited before response: ${code ?? signal}`),
 77				);
 78			};
 79			child.stdout.on("data", onData);
 80			child.once("error", onError);
 81			child.once("exit", onExit);
 82		});
 83	}
