 77	async function runSingleProcessScenario(
 78		state: ScenarioState,
 79		mode:
 80			| "tools-list"
 81			| "representative-read"
 82			| "concurrent-reads"
 83			| "sequential-reads",
 84		operation: (harness: PerformanceHarness) => Promise<void>,
 85	) {
 86		const scenarioStartedAt = performance.now();
