 88		try {
 89			harness = await createPerformanceHarness(mode);
 90		} catch (error) {
 91			state.durations.push(measuredDuration(scenarioStartedAt));
 92			recordFailure(state, 1, "setup", error);
 93		}
 94	
 95		if (harness) {
 96			try {
 97				state.serverMemory.push(observeServerRss(harness.pid, 1, "initialized"));
 98				await operation(harness);
 99			} catch (error) {
100				if (state.durations.length === 0) {
101					state.durations.push(measuredDuration(scenarioStartedAt));
102				}
103				recordFailure(state, 1, "operation", error);
104			} finally {
105				await closeHarness(
106					state,
107					harness,
108					Math.max(state.completedIterations, 1),
109				);
110			}
111		}
112		return finalizeScenario(state, measuredDuration(scenarioStartedAt));
113	}
